**Question:** write a custom hook that syncs state with `localStorage` — reads the initial value, keeps both in sync, returns a value and setter, and handles a changing key.

## The hook

```javascript
import { useState, useEffect, useCallback, useRef } from 'react';

function readValue(key, fallback) {
  try {
    const raw = window.localStorage.getItem(key);
    return raw === null ? fallback : JSON.parse(raw);
  } catch {
    // Corrupt JSON, or storage blocked (Safari private mode, disabled cookies).
    return fallback;
  }
}

export function useLocalStorage(key, initialValue) {
  // Lazy initializer — reads storage once on mount, not on every render.
  const [value, setValue] = useState(() => readValue(key, initialValue));

  // Track the key so a change can re-read rather than overwrite.
  const previousKey = useRef(key);

  useEffect(() => {
    if (previousKey.current !== key) {
      previousKey.current = key;
      setValue(readValue(key, initialValue));   // load the NEW key's value
      return;
    }

    try {
      window.localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // Quota exceeded or storage unavailable — keep React state working.
    }
  }, [key, value, initialValue]);

  // Accepts a value or an updater, like useState.
  const setStoredValue = useCallback((next) => {
    setValue((current) => (typeof next === 'function' ? next(current) : next));
  }, []);

  const remove = useCallback(() => {
    try {
      window.localStorage.removeItem(key);
    } catch { /* ignore */ }
    setValue(initialValue);
  }, [key, initialValue]);

  return [value, setStoredValue, remove];
}
```

```javascript
const [theme, setTheme] = useLocalStorage('theme', 'light');
setTheme('dark');
setTheme((t) => (t === 'dark' ? 'light' : 'dark'));
```

